import { Request, Response, Router } from "express";
import { AddTaskUseCase } from "../application/AddTaskUseCase";
import { AssignTaskUseCase } from "../application/AssignTaskUseCase";
import { ListTasksUseCase } from "../application/ListTasksUseCase";
import { MarkTaskDoneUseCase } from "../application/MarkTaskDoneUseCase";
import {
  BadRequestError,
  asyncHandler,
  bodyOf,
  optionalString,
  requiredString,
} from "./httpSupport";

export interface TaskUseCases {
  addTask: AddTaskUseCase;
  assignTask: AssignTaskUseCase;
  listTasks: ListTasksUseCase;
  markTaskDone: MarkTaskDoneUseCase;
}

export class TaskController {
  constructor(private readonly useCases: TaskUseCases) {}

  routes(): Router {
    const router = Router();
    const base = "/projects/:projectId/tasks";
    router.post(base, asyncHandler((req, res) => this.add(req, res)));
    router.get(base, asyncHandler((req, res) => this.list(req, res)));
    router.put(
      `${base}/:taskId/assignee`,
      asyncHandler((req, res) => this.assign(req, res)),
    );
    router.post(
      `${base}/:taskId/done`,
      asyncHandler((req, res) => this.markDone(req, res)),
    );
    return router;
  }

  private async add(req: Request, res: Response): Promise<void> {
    const body = bodyOf(req);
    const dueDate = body["dueDate"];
    if (dueDate !== undefined && dueDate !== null && typeof dueDate !== "string") {
      throw new BadRequestError("dueDate must be a string");
    }
    const task = await this.useCases.addTask.execute({
      projectId: String(req.params["projectId"]),
      title: requiredString(body, "title"),
      description: optionalString(body, "description") ?? "",
      dueDate,
      status: optionalString(body, "status"),
    });
    res.status(201).json(task);
  }

  private async list(req: Request, res: Response): Promise<void> {
    const tasks = await this.useCases.listTasks.execute({
      projectId: String(req.params["projectId"]),
      status: queryString(req, "status"),
      assigneeId: queryString(req, "assigneeId"),
    });
    res.json(tasks);
  }

  private async assign(req: Request, res: Response): Promise<void> {
    const task = await this.useCases.assignTask.execute({
      projectId: String(req.params["projectId"]),
      taskId: String(req.params["taskId"]),
      assigneeId: requiredString(bodyOf(req), "assigneeId"),
    });
    res.json(task);
  }

  private async markDone(req: Request, res: Response): Promise<void> {
    const task = await this.useCases.markTaskDone.execute({
      projectId: String(req.params["projectId"]),
      taskId: String(req.params["taskId"]),
    });
    res.json(task);
  }
}

function queryString(req: Request, key: string): string | undefined {
  const value: unknown = req.query[key];
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== "string") {
    throw new BadRequestError(`${key} must be a single string`);
  }
  return value;
}

